package au.aumanet.app;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.net.Uri;import android.os.*;import androidx.core.content.ContextCompat;import java.util.concurrent.atomic.*;
/** Explicit bounded OTA owner; pending intents can stop only their exact operation. */
public final class NodeUpdateService extends Service {
 static final String CHANNEL="aumanet-node-update";private static final String START="au.aumanet.nodeupdate.START",STOP="au.aumanet.nodeupdate.STOP";private static final Object LOCK=new Object();private static final int ID=7281;private static volatile NodeUpdateService active;private static volatile NodeUpdateController.Operation pending;
 private final Handler main=new Handler(Looper.getMainLooper());private volatile NodeUpdateController.Operation owned;private PowerManager.WakeLock wake;private volatile boolean foreground;
 static void start(Context context,NodeUpdateController.Operation operation){if(!ServiceNotificationAccess.allowed(context,CHANNEL))throw new IllegalStateException("Enable firmware update notifications first");synchronized(LOCK){if(active!=null||pending!=null)throw new IllegalStateException("An update service is already owned");pending=operation;}try{ContextCompat.startForegroundService(context,new Intent(context,NodeUpdateService.class).setAction(START).putExtra("operationId",operation.id).putExtra("serviceToken",operation.serviceToken).putExtra("generation",operation.generation));}catch(RuntimeException failed){synchronized(LOCK){if(pending==operation)pending=null;}throw failed;}}
 static boolean ready(NodeUpdateController.Operation operation){NodeUpdateService s=active;return s!=null&&s.owned==operation&&s.foreground&&NodeUpdateController.isCurrent(operation);}
 static void release(NodeUpdateController.Operation operation){synchronized(LOCK){if(pending==operation)pending=null;}NodeUpdateService s=active;if(s!=null&&s.owned==operation)s.main.post(()->s.finish(operation));}
 @Override public void onCreate(){super.onCreate();if(Build.VERSION.SDK_INT>=26)((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(new NotificationChannel(CHANNEL,"Node firmware update",NotificationManager.IMPORTANCE_LOW));}
 @Override public int onStartCommand(Intent intent,int flags,int startId){
  if(intent!=null&&STOP.equals(intent.getAction())){NodeUpdateController.Operation current=owned;if(current!=null&&active==this&&NodeUpdateServiceScope.matches(current.id,current.serviceToken,current.generation,intent.getStringExtra("operationId"),intent.getStringExtra("serviceToken"),intent.getLongExtra("generation",-1)))NodeUpdateController.stopOwned(current);else if(owned==null&&pending==null)stopSelf(startId);return START_NOT_STICKY;}
  NodeUpdateController.Operation request=pending;if(intent==null||!START.equals(intent.getAction())||request==null||!NodeUpdateServiceScope.matches(request.id,request.serviceToken,request.generation,intent.getStringExtra("operationId"),intent.getStringExtra("serviceToken"),intent.getLongExtra("generation",-1))||!NodeUpdateController.isCurrent(request)){if(owned==null)stopSelf(startId);return START_NOT_STICKY;}
  synchronized(LOCK){if(owned==request)return START_NOT_STICKY;if(owned!=null||active!=null&&active!=this){NodeUpdateController.stopOwned(request);return START_NOT_STICKY;}owned=request;active=this;if(pending==request)pending=null;}
  try{if(!ServiceNotificationAccess.allowed(this,CHANNEL)||!NodeUpdateController.isCurrent(request))throw new SecurityException();if(Build.VERSION.SDK_INT>=29)startForeground(ID,notification(request),ServiceInfo.FOREGROUND_SERVICE_TYPE_CONNECTED_DEVICE);else startForeground(ID,notification(request));foreground=true;wake=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"AuMaNET:NodeUpdate");wake.setReferenceCounted(false);wake.acquire(Math.max(1,request.deadline-SystemClock.elapsedRealtime()));main.post(health);}catch(RuntimeException failed){NodeUpdateController.stopOwned(request);finish(request);}return START_NOT_STICKY;
 }
 private Notification notification(NodeUpdateController.Operation request){Intent intent=new Intent(this,NodeUpdateService.class).setAction(STOP).setData(Uri.parse("aumanet://node-update/"+request.id+"/"+request.generation+"/"+request.serviceToken)).putExtra("operationId",request.id).putExtra("serviceToken",request.serviceToken).putExtra("generation",request.generation);PendingIntent stop=PendingIntent.getService(this,request.id.hashCode(),intent,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification.Builder builder=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,CHANNEL):new Notification.Builder(this);return builder.setSmallIcon(android.R.drawable.stat_sys_upload).setContentTitle("Updating node firmware").setContentText("Keep this phone near its node. Stop ends this update attempt.").setOngoing(true).addAction(new Notification.Action.Builder(android.R.drawable.ic_media_pause,"Stop",stop).build()).build();}
 private final Runnable health=new Runnable(){public void run(){NodeUpdateController.Operation request=owned;if(request==null)return;if(!NodeUpdateController.isCurrent(request)||SystemClock.elapsedRealtime()>=request.deadline||!ServiceNotificationAccess.allowed(NodeUpdateService.this,CHANNEL)){NodeUpdateController.stopOwned(request);finish(request);return;}main.postDelayed(this,1000);}};
 private void finish(NodeUpdateController.Operation request){if(owned!=request)return;main.removeCallbacks(health);synchronized(LOCK){if(pending==request)pending=null;}owned=null;foreground=false;if(wake!=null){if(wake.isHeld())wake.release();wake=null;}stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();}
 @Override public void onDestroy(){NodeUpdateController.Operation request=owned;if(request!=null){NodeUpdateController.stopOwned(request);finish(request);}synchronized(LOCK){if(active==this)active=null;}super.onDestroy();}
 @Override public IBinder onBind(Intent intent){return null;}
}
